<script setup lang="tsx">
import { computed, h, onMounted, reactive, ref } from 'vue';
import type { DataTableColumns } from 'naive-ui';import { NButton,NPopconfirm,NSpace,NTag } from 'naive-ui';
import { $t } from '@/locales';import { AI_ACTIONS,MODEL_FEATURES,MODEL_TYPES } from '@/constants/ai';import { createAIDeployment,deleteAIAlias,deleteAIDeployment,discoverAIModels,fetchAIAliases,fetchAIDeployments,fetchAIProviders,importAIDeployments,updateAIDeployment,updateAIDeploymentStatus,upsertAIAlias } from '@/service/api';import { useAuthStore } from '@/store/modules/auth';
defineOptions({name:'AIModels'});const auth=useAuthStore();const rows=ref<Api.AI.Deployment[]>([]);const aliases=ref<Api.AI.Alias[]>([]);const providers=ref<Api.AI.Provider[]>([]);const loading=ref(false);const query=reactive({page:1,page_size:20,keyword:'',status:''});const total=ref(0);const visible=ref(false);const editing=ref<Api.AI.Deployment|null>(null);const aliasVisible=ref(false);const aliasDeployment=ref<Api.AI.Deployment|null>(null);const aliasCode=ref('');const form=reactive({provider_id:'',code:'',remote_model_id:'',display_name:'',model_type:'chat',features:[] as string[],context_window:null as number|null,max_output_tokens:null as number|null});const can=(p:string)=>auth.userInfo.buttons.includes(p)||auth.userInfo.buttons.includes('*');
const discoveryVisible=ref(false);const discoveryLoading=ref(false);const discoveryProvider=ref('');const remoteModels=ref<Api.AI.RemoteModel[]>([]);const selectedRemote=ref<Array<string|number>>([]);const remoteKeyword=ref('');const importType=ref('chat');const importFeatures=ref<string[]>([]);
const importCandidates=computed(()=>{const keyword=remoteKeyword.value.trim().toLowerCase();return remoteModels.value.filter(x=>!x.imported&&(!keyword||x.id.toLowerCase().includes(keyword)||x.display_name.toLowerCase().includes(keyword)))});
function featureLabel(feature:string){const known=MODEL_FEATURES.find(item=>item===feature);return known?$t(`aiModel.features.${known}`):feature}
async function load(){loading.value=true;try{const [d,a,p]=await Promise.all([fetchAIDeployments(query),fetchAIAliases(),fetchAIProviders({page:1,page_size:100})]);if(d.data){rows.value=d.data.items;total.value=d.data.total}aliases.value=a.data||[];providers.value=p.data?.items||[]}finally{loading.value=false}}
function openEditor(row?:Api.AI.Deployment){editing.value=row||null;Object.assign(form,row?{provider_id:row.provider_id,code:row.code,remote_model_id:row.remote_model_id,display_name:row.display_name,model_type:row.model_type,features:[...(row.capabilities_json.features||[])],context_window:row.limits_json.context_window||null,max_output_tokens:row.limits_json.max_output_tokens||null}:{provider_id:'',code:'',remote_model_id:'',display_name:'',model_type:'chat',features:[],context_window:null,max_output_tokens:null});visible.value=true}
async function save(){const common={display_name:form.display_name,model_type:form.model_type,capabilities:{input_modalities:['text'],output_modalities:['text'],features:form.features},limits:{context_window:form.context_window||0,max_output_tokens:form.max_output_tokens||0},config:{}};const result=editing.value?await updateAIDeployment({id:editing.value.id,...common}):await createAIDeployment({provider_id:form.provider_id,code:form.code,remote_model_id:form.remote_model_id,...common,status:'enabled'});if(!result.error){visible.value=false;await load()}}
async function toggle(r:Api.AI.Deployment){await updateAIDeploymentStatus(r.id,r.status==='enabled'?'disabled':'enabled');await load()}
async function removeDeployment(r:Api.AI.Deployment){const {error}=await deleteAIDeployment(r.id);if(!error)await load()}
async function openDiscovery(){if(!discoveryProvider.value){discoveryProvider.value=providers.value.find(x=>x.status==='enabled')?.id||''}if(!discoveryProvider.value){window.$message?.warning('请先选择可用的模型供应商');return}remoteModels.value=[];selectedRemote.value=[];remoteKeyword.value='';discoveryVisible.value=true;discoveryLoading.value=true;try{const {data,error}=await discoverAIModels(discoveryProvider.value);if(!error&&data)remoteModels.value=data.items}finally{discoveryLoading.value=false}}
function deploymentCode(id:string){const normalized=id.toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'');return (normalized||'model').slice(0,64)}
async function importSelected(){const selected=new Set(selectedRemote.value.map(String));const items=remoteModels.value.filter(x=>selected.has(x.id)).map(x=>({provider_id:discoveryProvider.value,code:deploymentCode(x.id),remote_model_id:x.id,display_name:x.display_name||x.id,model_type:importType.value,capabilities:{input_modalities:['text'],output_modalities:['text'],features:importFeatures.value},limits:{context_window:0,max_output_tokens:0},status:'enabled',config:{}}));if(!items.length)return;const {error}=await importAIDeployments(items);if(!error){discoveryVisible.value=false;await load()}}
function openAlias(r:Api.AI.Deployment){aliasDeployment.value=r;aliasCode.value='';aliasVisible.value=true}async function bindAlias(){const code=aliasCode.value.trim();if(!aliasDeployment.value||!code)return;const {error}=await upsertAIAlias(code,aliasDeployment.value.id);if(!error){aliasVisible.value=false;await load()}}async function removeAlias(code:string){const {error}=await deleteAIAlias(code);if(!error)await load()}
const columns=computed<DataTableColumns<Api.AI.Deployment>>(()=>[{title:'代码',key:'code',minWidth:120},{title:'远端模型',key:'remote_model_id',minWidth:180},{title:'类型',key:'model_type',width:110},{title:'能力',key:'capabilities_json',minWidth:220,render:r=>h(NSpace,{size:4},{default:()=>r.capabilities_json.features.map(x=>h(NTag,{size:'small'},{default:()=>featureLabel(x)}))})},{title:$t('aiModel.alias'),key:'aliases',minWidth:180,render:r=>h(NSpace,{size:4},{default:()=>aliases.value.filter(a=>a.deployment_id===r.id).map(a=>h(NTag,{closable:can(AI_ACTIONS.aliasDelete),onClose:()=>removeAlias(a.code)},{default:()=>a.code}))})},{title:'状态',key:'status',width:100,render:r=>h(NTag,{type:r.status==='enabled'?'success':'default'},{default:()=>$t(`aiModel.${r.status}`)})},{title:'操作',key:'actions',width:310,render:r=>h(NSpace,null,{default:()=>[can(AI_ACTIONS.deploymentUpdate)?h(NButton,{size:'small',onClick:()=>openEditor(r)},{default:()=>$t('common.edit')}):null,can(AI_ACTIONS.aliasUpsert)?h(NButton,{size:'small',onClick:()=>openAlias(r)},{default:()=>$t('aiModel.bindAlias')}):null,can(AI_ACTIONS.deploymentStatus)?h(NButton,{size:'small',onClick:()=>toggle(r)},{default:()=>$t(`aiModel.${r.status==='enabled'?'disabled':'enabled'}`)}):null,can(AI_ACTIONS.deploymentDelete)?h(NPopconfirm,{onPositiveClick:()=>removeDeployment(r)},{trigger:()=>h(NButton,{size:'small',type:'error'},{default:()=>$t('common.delete')}),default:()=>$t('aiModel.deleteConfirm')}):null].filter(Boolean)})}]);onMounted(load);
</script>
<template><div class="flex-col-stretch gap-16px"><NCard title="模型目录" :bordered="false"><NSpace><NInput v-model:value="query.keyword" placeholder="搜索模型" @keyup.enter="load"/><NButton @click="load">查询</NButton><NSelect v-model:value="discoveryProvider" class="w-180px" placeholder="选择供应商" :options="providers.filter(x=>x.status==='enabled').map(x=>({label:x.name,value:x.id}))"/><NButton v-if="can(AI_ACTIONS.deploymentImport)&&can(AI_ACTIONS.providerDiscover)" @click="openDiscovery">远端发现</NButton><NButton v-if="can(AI_ACTIONS.deploymentCreate)" type="primary" @click="openEditor()">手工新增</NButton></NSpace></NCard><NCard :bordered="false"><NDataTable :columns="columns" :data="rows" :loading="loading" :scroll-x="1200"/><NPagination v-model:page="query.page" class="mt-16px justify-end" :item-count="total" :page-size="query.page_size" @update:page="load"/></NCard>
<NModal v-model:show="visible" preset="card" :title="editing?$t('aiModel.editTitle'):$t('aiModel.createTitle')" class="w-660px max-w-90vw"><NAlert v-if="!editing" type="warning" class="mb-12px">手工模型必须明确确认类型、能力和限制。</NAlert><NForm :model="form" label-placement="left" label-width="110"><NFormItem label="供应商"><NSelect v-model:value="form.provider_id" :disabled="Boolean(editing)" :options="providers.filter(x=>x.status==='enabled').map(x=>({label:x.name,value:x.id}))"/></NFormItem><NFormItem label="代码"><NInput v-model:value="form.code" :disabled="Boolean(editing)"/></NFormItem><NFormItem label="远端模型 ID"><NInput v-model:value="form.remote_model_id" :disabled="Boolean(editing)"/></NFormItem><NFormItem label="显示名称"><NInput v-model:value="form.display_name"/></NFormItem><NFormItem label="模型类型"><NSelect v-model:value="form.model_type" :options="MODEL_TYPES.map(x=>({label:x,value:x}))"/></NFormItem><NFormItem label="能力"><NCheckboxGroup v-model:value="form.features"><NSpace><NCheckbox v-for="x in MODEL_FEATURES" :key="x" :value="x" :label="featureLabel(x)"/></NSpace></NCheckboxGroup></NFormItem><NFormItem label="上下文窗口"><NInputNumber v-model:value="form.context_window" :min="0"/></NFormItem><NFormItem label="最大输出"><NInputNumber v-model:value="form.max_output_tokens" :min="0"/></NFormItem></NForm><template #footer><NSpace justify="end"><NButton @click="visible=false">取消</NButton><NButton type="primary" @click="save">保存</NButton></NSpace></template></NModal><NModal v-model:show="discoveryVisible" preset="card" title="发现并导入模型" class="w-820px max-w-90vw"><NAlert type="warning" class="mb-12px">供应商未提供可信能力元数据。请确认本批模型的类型和能力后再导入。</NAlert><NSpace class="mb-12px"><NInput v-model:value="remoteKeyword" :disabled="discoveryLoading" placeholder="搜索模型 ID"/><NSelect v-model:value="importType" class="w-150px" :disabled="discoveryLoading" :options="MODEL_TYPES.map(x=>({label:x,value:x}))"/></NSpace><NCheckboxGroup v-model:value="importFeatures" class="mb-12px" :disabled="discoveryLoading"><NSpace><NCheckbox v-for="x in MODEL_FEATURES" :key="x" :value="x" :label="featureLabel(x)"/></NSpace></NCheckboxGroup><NDataTable v-model:checked-row-keys="selectedRemote" :loading="discoveryLoading" max-height="min(400px, 46vh)" virtual-scroll :row-key="(r:Api.AI.RemoteModel)=>r.id" :columns="[{type:'selection'},{title:'模型 ID',key:'id'},{title:'名称',key:'display_name'}]" :data="importCandidates"/><template #footer><NSpace justify="end"><NButton @click="discoveryVisible=false">取消</NButton><NButton type="primary" :disabled="discoveryLoading||selectedRemote.length===0" @click="importSelected">导入所选</NButton></NSpace></template></NModal><NModal v-model:show="aliasVisible" preset="card" :title="$t('aiModel.bindAlias')" class="w-460px max-w-90vw"><NInput v-model:value="aliasCode" maxlength="64" placeholder="general-chat" @keyup.enter="bindAlias"/><template #footer><NButton type="primary" :disabled="!aliasCode.trim()" @click="bindAlias">绑定</NButton></template></NModal></div></template>
